#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> Timeline {
        let mut tl = Timeline::new();
        tl.record(35, "logout");
        tl.record(10, "boot");
        tl.record(20, "login");
        tl
    }

    #[test]
    fn between_is_ordered_and_inclusive() {
        let tl = sample();
        assert_eq!(tl.between(15, 40), vec!["login", "logout"]);
        assert_eq!(tl.between(10, 20), vec!["boot", "login"]);
        assert_eq!(tl.between(0, u64::MAX), vec!["boot", "login", "logout"]);
        assert!(tl.between(21, 34).is_empty());
        assert!(tl.between(30, 5).is_empty());
    }

    #[test]
    fn latest_before() {
        let tl = sample();
        assert_eq!(tl.latest_at_or_before(34), Some((20, "login")));
        assert_eq!(tl.latest_at_or_before(20), Some((20, "login")));
        assert_eq!(tl.latest_at_or_before(9), None);
    }

    #[test]
    fn first_after_strict() {
        let tl = sample();
        assert_eq!(tl.first_after(10), Some((20, "login")));
        assert_eq!(tl.first_after(0), Some((10, "boot")));
        assert_eq!(tl.first_after(35), None);
        assert_eq!(tl.first_after(u64::MAX), None);
    }

    #[test]
    fn replace_returns_old() {
        let mut tl = sample();
        assert_eq!(tl.record(20, "relogin"), Some("login".to_string()));
        assert_eq!(tl.record(50, "shutdown"), None);
        assert_eq!(tl.between(20, 50), vec!["relogin", "logout", "shutdown"]);
    }
}
